mapper.select:
SELECT s.settlement_id as settlementId, s.gym_id as gymId, g.gym_name as gymName, s.commission, s.settled_at as settledAt, s.commission_rate as commissionRate, s.settle_month as settleMonth, s.status, s.expense_id as expenseId FROM "h_settlement" s LEFT JOIN "h_gym" g ON s.gym_id = g.gym_id
AND s.status = #{pager.searchKeyword}
AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{pager.month}
ORDER BY s.commission DESC ORDER BY s.commission ASC ORDER BY s.settle_month ASC, s.settlement_id ASC ORDER BY s.settle_month DESC, s.settlement_id DESC
LIMIT #{pager.pageSize} OFFSET #{pager.offset}

SELECT COUNT(*)
FROM "h_settlement" s


        AND s.status = #{pager.searchKeyword}


        AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{pager.month}

SELECT s.settlement_id as settlementId, s.gym_id as gymId, g.gym_name as gymName, s.commission, s.settled_at as settledAt, s.commission_rate as commissionRate, s.settle_month as settleMonth, s.status, s.expense_id as expenseId FROM "h_settlement" s LEFT JOIN "h_gym" g ON s.gym_id = g.gym_id
AND s.status = #{pager.searchKeyword}
AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{pager.month}
ORDER BY s.settle_month DESC, s.settlement_id DESC

SELECT
    COALESCE((SELECT SUM(p.pay_price) FROM "h_payment" p
              WHERE p.gym_id = g.gym_id
              AND TO_CHAR(p.pay_date, 'YYYY-MM') = #{month}
             ), 0) AS salesTotal,
    COALESCE((SELECT SUM(COALESCE(NULLIF(e.expense_price, 0), s.commission, 0))
              FROM "h_expense" e
              LEFT JOIN "h_settlement" s ON s.expense_id = e.expense_id
              WHERE e.gym_id = g.gym_id
              AND TO_CHAR(e.expense_date, 'YYYY-MM') = #{month}
             ), 0) AS expenseTotal,
    COALESCE((SELECT SUM(CASE WHEN s.status = '지급' THEN s.commission ELSE 0 END) FROM "h_settlement" s
              WHERE s.gym_id = g.gym_id
              AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{month}
             ), 0) AS commissionPaid,
    COALESCE((SELECT COUNT(*) FROM "h_settlement" s
              WHERE s.gym_id = g.gym_id AND s.status = '미지급'
              AND TO_CHAR(s.settle_month, 'YYYY-MM') = #{month}
             ), 0) AS commissionPending,
    COALESCE((SELECT SUM(e.expense_price) FROM "h_expense" e
              JOIN "h_contract_data" d ON e.data_id = d.data_id
              WHERE d.contract = 2 AND e.gym_id = g.gym_id
              AND TO_CHAR(e.expense_date, 'YYYY-MM') = #{month}
             ), 0) AS wagePaid,
    COALESCE((SELECT COUNT(*) FROM "h_contract_data" d
              WHERE d.sender_id = #{username} AND d.contract = 2
                AND d.status IN ('SIGNED', 'ACTIVE')
                AND d.data_id NOT IN (SELECT data_id FROM "h_expense" WHERE data_id IS NOT NULL)
             ), 0) AS wagePending
FROM "h_member" g
WHERE g.username = #{username}

SELECT CAST(COALESCE(SUM(pay_price), 0) * #{rate} AS int8)
FROM "h_payment"
WHERE gym_id = #{gymId} AND pay_date >= #{startDate} AND pay_date <= #{endDate}

SELECT e.expense_id as expenseId, e.gym_id as gymId, e.data_id as dataId, s.settlement_id as settlementId, e.expense_name as expenseName, e.expense_date as expenseDate, COALESCE(NULLIF(e.expense_price, 0), s.commission, 0) as expensePrice, COALESCE(NULLIF(e.expense_rate, 0), s.commission_rate, 0) as expenseRate FROM "h_expense" e LEFT JOIN "h_settlement" s ON s.expense_id = e.expense_id WHERE e.gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(e.expense_date, 'YYYY-MM') = #{pager.month}
AND e.expense_name LIKE CONCAT('%', #{pager.searchKeyword}, '%')
ORDER BY COALESCE(NULLIF(e.expense_price, 0), s.commission, 0) DESC ORDER BY COALESCE(NULLIF(e.expense_price, 0), s.commission, 0) ASC ORDER BY e.expense_date ASC, e.expense_id ASC ORDER BY e.expense_date DESC, e.expense_id DESC
LIMIT #{pager.pageSize} OFFSET #{pager.offset}

SELECT COUNT(*) FROM "h_expense" WHERE gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(expense_date, 'YYYY-MM') = #{pager.month}
AND expense_name LIKE CONCAT('%', #{pager.searchKeyword}, '%')

SELECT COALESCE(SUM(COALESCE(NULLIF(e.expense_price, 0), s.commission, 0)), 0) FROM "h_expense" e LEFT JOIN "h_settlement" s ON s.expense_id = e.expense_id WHERE e.gym_id = (SELECT gym_id FROM "h_member" WHERE username = #{username})
AND TO_CHAR(e.expense_date, 'YYYY-MM') = #{pager.month}
AND e.expense_name LIKE CONCAT('%', #{pager.searchKeyword}, '%')

SELECT COUNT(*)
FROM "h_contract_data"
WHERE data_id = #{dataId}
  AND sender_id = #{username}
  AND contract = 2
  AND status IN ('SIGNED', 'ACTIVE')
  AND NOT EXISTS (
      SELECT 1 FROM "h_expense" e WHERE e.data_id = #{dataId}
  )

mapper.delete:
DELETE FROM "h_expense" e
USING "h_member" m
WHERE e.expense_id = #{expenseId}
  AND e.gym_id = m.gym_id
  AND m.username = #{username}
  AND UPPER(m.role) = 'OWNER'

